#[inductive(page_mk_block_tokens)]
fn page_mk_block_tokens_inductive(pre: Self, post: Self, thread_id: ThreadId, page_id: PageId, old_num_blocks: nat, new_num_blocks: nat, block_size: nat) {
    assert(pre.inv_block_id_valid());
    assert(post.inv_block_id_valid()) by {
        assert forall |block_id: BlockId| post.block.dom().contains(block_id)
            implies post.inv_block_id_valid_for_block(block_id) by {
            if pre.block.dom().contains(block_id) {
                assert(pre.inv_block_id_valid_for_block(block_id));
            }
        }
    }
    assert forall |block_id: BlockId| post.block.dom().contains(block_id)
        implies post.inv_block_id_valid_for_block(block_id)
    by {
        if pre.block.dom().contains(block_id) {
            assert(pre.inv_block_id_valid_for_block(block_id));
            assert(post.block[block_id] == pre.block[block_id]);
        } else {
            assert(block_id.page_id == page_id);
            assert(old_num_blocks <= block_id.idx < new_num_blocks);
            assert(Self::okay_to_add_block(pre.thread_local_state[thread_id], page_id,
                block_id.idx, block_size));
            reveal(Mim::State::okay_to_add_block);
            assert(post.block[block_id].heap_id == None);
            assert(post.block[block_id].page_shared_access
                == post.thread_local_state[thread_id].pages[block_id.page_id].shared_access);
            assert(pre.thread_local_state[thread_id].pages.dom().contains(block_id.page_id_for_slice()));
            assert(pre.thread_local_state[thread_id].pages[block_id.page_id_for_slice()].is_enabled);
            assert(pre.thread_local_state[thread_id].pages[block_id.page_id_for_slice()].shared_access
                == post.block[block_id].page_slice_shared_access);
            assert(post.inv_block_id_valid_for_block(block_id)) by {
                assert(post.thread_of_segment.dom().contains(block_id.page_id.segment_id));
                assert(post.thread_local_state[thread_id].pages.dom().contains(block_id.page_id));
                assert(post.thread_local_state[thread_id].pages[block_id.page_id].is_enabled);
                assert(post.thread_local_state[thread_id].pages[block_id.page_id].offset == 0);
                assert(post.thread_local_state[thread_id].pages[block_id.page_id].block_size == block_id.block_size);
                assert(0 <= block_id.idx < post.thread_local_state[thread_id].pages[block_id.page_id].num_blocks);
                assert(post.thread_local_state[thread_id].pages.dom().contains(block_id.page_id_for_slice()));
                assert(post.thread_local_state[thread_id].pages[block_id.page_id_for_slice()].is_enabled);
                assert(post.thread_local_state[thread_id].pages[block_id.page_id_for_slice()].shared_access
                    == post.block[block_id].page_slice_shared_access);
                assert(post.thread_local_state[thread_id].pages[block_id.page_id_for_slice()].offset
                    == block_id.page_id_for_slice().idx - block_id.page_id.idx);
                    assert(post.thread_local_state[thread_id].segments[block_id.page_id.segment_id]
                        == pre.thread_local_state[thread_id].segments[block_id.page_id.segment_id]);
                assert(post.thread_local_state[thread_id].segments.dom().contains(block_id.page_id.segment_id));
                assert(post.thread_local_state[thread_id].segments[block_id.page_id.segment_id].is_enabled);
                assert(post.block[block_id].segment_shared_access
                    == post.segment_shared_access[block_id.page_id.segment_id]);
                    assert(post.segment_shared_access == pre.segment_shared_access);
                    assert(post.thread_of_segment == pre.thread_of_segment);
                assert(post.block[block_id].segment_shared_access
                    == pre.segment_shared_access[block_id.page_id.segment_id]);
                assert(post.segment_shared_access[block_id.page_id.segment_id]
                    == pre.segment_shared_access[block_id.page_id.segment_id]);
                assert(post.thread_local_state[thread_id].segments[block_id.page_id.segment_id].shared_access
                    == post.segment_shared_access[block_id.page_id.segment_id]);
                assert(pre.inv_segment_shared_access_eq());
                assert(pre.inv_thread_of_segment1());
                assert(pre.segment_shared_access.dom().contains(block_id.page_id.segment_id));
                assert(pre.segment_shared_access[block_id.page_id.segment_id]
                    == pre.thread_local_state[thread_id].segments[block_id.page_id.segment_id].shared_access);
                assert(Mim::State::block_properties(
                    post.thread_local_state[thread_id], block_id, post.block[block_id]));
            }
        }
    }
}

proof fn block_map_with_len(blocks: Map<BlockId, BlockState>, page_id: PageId, len: int)
    requires
        blocks.len() >= len,
        len >= 0,
        forall |block_id: BlockId| blocks.dom().contains(block_id) ==>
            block_id.page_id == page_id && 0 <= block_id.idx < len,
        forall |bid1: BlockId, bid2: BlockId|
            blocks.dom().contains(bid1) && blocks.dom().contains(bid2)
            && bid1.page_id == bid2.page_id && bid1.idx == bid2.idx
            ==> bid1 == bid2
    ensures
        blocks.len() > len ==> false,
        forall |i| 0 <= i < blocks.len() ==> Self::blocks_has(blocks, page_id, i)
    decreases len,
{
    if len == 0 {
        if (blocks.len() > len) {
