fn segment_enable_inductive(pre: Self, post: Self, thread_id: ThreadId, segment_id: SegmentId, shared_access: SegmentSharedAccess) { }

    #[inductive(create_page_mk_tokens)]
    fn create_page_mk_tokens_inductive(pre: Self, post: Self, thread_id: ThreadId, page_id: PageId, n_slices: nat, block_size: nat, page_map: Map<PageId, PageState>) {

    }

    #[inductive(page_enable)]
    fn page_enable_inductive(pre: Self, post: Self, thread_id: ThreadId, page_id: PageId, n_slices: nat, page_map: Map<PageId, PageState>, psa_map: Map<PageId, PageSharedAccess>) { }

    #[inductive(page_mk_block_tokens)]
    fn page_mk_block_tokens_inductive(pre: Self, post: Self, thread_id: ThreadId, page_id: PageId, old_num_blocks: nat, new_num_blocks: nat, block_size: nat) {
        assert(pre.inv_block_id_valid());
        assert(post.inv_block_id_valid()) by {
            assert forall |block_id: BlockId| post.block.dom().contains(block_id)
                implies post.inv_block_id_valid_for_block(block_id) by {
                if pre.block.dom().contains(block_id) {
                    assert(pre.inv_block_id_valid_for_block(block_id));
                }
            }
        }
        assert forall |block_id: BlockId| post.block.dom().contains(block_id)
            implies post.inv_block_id_valid_for_block(block_id)
        by {
            if pre.block.dom().contains(block_id) {
                assert(pre.inv_block_id_valid_for_block(block_id));
                assert(post.block[block_id] == pre.block[block_id]);
            } else {
                assert(block_id.page_id == page_id);
                assert(old_num_blocks <= block_id.idx < new_num_blocks);
                assert(Self::okay_to_add_block(pre.thread_local_state[thread_id], page_id,
                    block_id.idx, block_size));
                reveal(Mim::State::okay_to_add_block);
                assert(post.block[block_id].heap_id == None);
                assert(post.block[block_id].page_shared_access
                    == post.thread_local_state[thread_id].pages[block_id.page_id].shared_access);
                assert(pre.thread_local_state[thread_id].pages.dom().contains(block_id.page_id_for_slice()));
                assert(pre.thread_local_state[thread_id].pages[block_id.page_id_for_slice()].is_enabled);
                assert(pre.thread_local_state[thread_id].pages[block_id.page_id_for_slice()].shared_access
                    == post.block[block_id].page_slice_shared_access);
                assert(post.inv_block_id_valid_for_block(block_id)) by {
                    assert(post.thread_of_segment.dom().contains(block_id.page_id.segment_id));
                    assert(post.thread_local_state[thread_id].pages.dom().contains(block_id.page_id));
                    assert(post.thread_local_state[thread_id].pages[block_id.page_id].is_enabled);
                    assert(post.thread_local_state[thread_id].pages[block_id.page_id].offset == 0);
